import{_ as o,o as d,c as e,ag as a}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"Matt Pocock Skills：AI 编程的工程纪律","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-tools/mattpocock-skills-deep-analysis.md","filePath":"topics/ai-tools/mattpocock-skills-deep-analysis.md"}'),r={name:"topics/ai-tools/mattpocock-skills-deep-analysis.md"};function i(s,t,l,n,c,h){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="matt-pocock-skills-ai-编程的工程纪律" tabindex="-1">Matt Pocock Skills：AI 编程的工程纪律 <a class="header-anchor" href="#matt-pocock-skills-ai-编程的工程纪律" aria-label="Permalink to &quot;Matt Pocock Skills：AI 编程的工程纪律&quot;">​</a></h1><blockquote><p>来源：mattpocock/skills（GitHub，23k stars / 3 周）· LangLabs 官方文档 · CSDN 技术解构（2026-07-07） 整理：2026-07-09</p></blockquote><hr><h2 id="零、身份确认" tabindex="-1">零、身份确认 <a class="header-anchor" href="#零、身份确认" aria-label="Permalink to &quot;零、身份确认&quot;">​</a></h2><ul><li><strong>作者</strong>：Matt Pocock，Total TypeScript 创始人，TypeScript 领域顶级布道者</li><li><strong>项目</strong>：<a href="https://github.com/mattpocock/skills" target="_blank" rel="noreferrer">mattpocock/skills</a>，MIT 开源</li><li><strong>数据</strong>：开源三周 23,000+ stars，60,000+ newsletter 订阅</li><li><strong>定位</strong>：Agent skills for disciplined software engineering — grilling, TDD, diagnosis, and architecture, not vibe coding</li></ul><hr><h2 id="一、核心理念-模型越强-技能越简单" tabindex="-1">一、核心理念：模型越强，技能越简单 <a class="header-anchor" href="#一、核心理念-模型越强-技能越简单" aria-label="Permalink to &quot;一、核心理念：模型越强，技能越简单&quot;">​</a></h2><p>这是理解 mattpocock-skills 的第一句话。&quot;模型越强，技能越简单&quot;——这与 GSD、BMAD、Spec-Kit 等&quot;流程控制工具&quot;形成了根本对立。</p><h3 id="两个范式" tabindex="-1">两个范式 <a class="header-anchor" href="#两个范式" aria-label="Permalink to &quot;两个范式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>流程控制工具（GSD/BMAD）</th><th>mattpocock-skills</th></tr></thead><tbody><tr><td>核心理念</td><td>控制流程，剥夺开发者控制权</td><td>自由灵活，开发者掌握主导权</td></tr><tr><td>技能粒度</td><td>大而全的流程（&quot;做项目&quot;）</td><td>小而独立的技能（&quot;做需求访谈&quot;）</td></tr><tr><td>可组合性</td><td>低——流程是线性固定步骤</td><td>高——按需组合，顺序自由</td></tr><tr><td>可修改性</td><td>低——修改流程 = 修改整个框架</td><td>高——每个 SKILL.md 独立可改</td></tr><tr><td>信任模型</td><td>不信任开发者（流程强制约束）</td><td>信任开发者（技能是工具，不替代判断）</td></tr><tr><td>适用场景</td><td>标准化、重复性强的项目</td><td>需要快速迭代和灵活调整的开发</td></tr></tbody></table><p><strong>Pocock 的原话</strong>：&quot;Skills are designed to be small, easy to adapt, and composable. They work with any model. Hack around with them. Make them your own. Enjoy.&quot;</p><h3 id="深层哲学-技能是-语法-不是-剧本" tabindex="-1">深层哲学：技能是&quot;语法&quot;，不是&quot;剧本&quot; <a class="header-anchor" href="#深层哲学-技能是-语法-不是-剧本" aria-label="Permalink to &quot;深层哲学：技能是&quot;语法&quot;，不是&quot;剧本&quot;&quot;">​</a></h3><p>GSD 试图写一个&quot;剧本&quot;——规定每一步做什么、什么时候做、谁来做。Pocock 的技能是&quot;语法&quot;——定义了&quot;怎么做&quot;的模式，但&quot;做什么&quot;和&quot;什么时候做&quot;完全由开发者决定。</p><p><strong>类比：</strong> GSD 是宜家说明书（第 1 步拧螺丝 A，第 2 步装面板 B），mattpocock-skills 是工具箱（锤子、螺丝刀、卷尺——按需取用，组合自由）。</p><hr><h2 id="二、四个失败模式-对-ai-工程学-缺失的诊断" tabindex="-1">二、四个失败模式：对&quot;AI 工程学&quot;缺失的诊断 <a class="header-anchor" href="#二、四个失败模式-对-ai-工程学-缺失的诊断" aria-label="Permalink to &quot;二、四个失败模式：对&quot;AI 工程学&quot;缺失的诊断&quot;">​</a></h2><p>Pocock 在 README 中归纳了四个 AI 编码助手的失败模式。这不是抱怨——这是一位有数十年工程经验的开发者，把问题树和解决方案树逐层对齐的结果。</p><h3 id="模式一-agent-没做你想要的事" tabindex="-1">模式一：Agent 没做你想要的事 <a class="header-anchor" href="#模式一-agent-没做你想要的事" aria-label="Permalink to &quot;模式一：Agent 没做你想要的事&quot;">​</a></h3><p><strong>引述</strong>：Pocock 引用《程序员修炼之道》——&quot;没有人真正知道自己想要什么。&quot;（David Thomas &amp; Andrew Hunt）</p><p><strong>本质</strong>：这不是 AI 的问题——这是人类沟通的根本问题。过去你面对的是一个能主动追问的人类开发者，现在你面对的是一个从不敢说&quot;我不明白&quot;的模型。<strong>AI 的&quot;沉默&quot;让含混的需求变成了致命的代码。</strong></p><p><strong>解决方案</strong>：强制开启结构化的追问环节（grilling session）——让 Agent 在写任何代码前，变成一位挑剔的架构师，从功能范围、边界条件、错误处理、性能要求、技术栈约束、测试策略等维度连续追问，直到所有模糊地带被扫清。</p><p><strong>对应技能</strong>：</p><table tabindex="0"><thead><tr><th>技能</th><th>分类</th><th>定位</th></tr></thead><tbody><tr><td><code>/grill-me</code></td><td>Productivity</td><td>通用需求深访，非代码场景</td></tr><tr><td><code>/grill-with-docs</code></td><td>Engineering</td><td>工程级深访，附带领域语言建模和 ADR</td></tr></tbody></table><h3 id="模式二-agent-表达过于啰嗦" tabindex="-1">模式二：Agent 表达过于啰嗦 <a class="header-anchor" href="#模式二-agent-表达过于啰嗦" aria-label="Permalink to &quot;模式二：Agent 表达过于啰嗦&quot;">​</a></h3><p><strong>引述</strong>：Pocock 引用 Eric Evans《领域驱动设计》——&quot;有了通用语言，开发者之间的对话和代码的表达都源自同一个领域模型。&quot;</p><p><strong>本质</strong>：不是 token 浪费的问题——是认知负载。当开发者和 AI 说不同的语言时，沟通成本是线性的，但理解偏差是指数的。Pocock 自己的例子：没有共享语言时，&quot;课程中某个 section 下的 lesson 被赋予文件系统中的实际位置时出现问题&quot;；有共享语言后，就是&quot;物化级联（materialization cascade）出了问题&quot;。</p><p><strong>解决方案</strong>：CONTEXT.md —— 一个共享语言文件，Agent 在每次交互前读取。这不是两个独立功能的拼接，而是 <code>grill-with-docs</code> 的统一流程：在需求深访的过程中，同步提炼领域术语并写入 CONTEXT.md，同时将技术决策记录为 ADR。</p><p><strong>Pocock 的评价</strong>：共享语言&quot;可能是整个仓库中最酷的技术&quot;——它带来的好处远超减少啰嗦本身：变量和函数的命名会自动收敛到一致风格；代码库对 Agent 来说变得更可导航；Agent 花费更少的 token 在&quot;思考&quot;上，因为它拥有了一套更精炼的语言系统。</p><h3 id="模式三-代码跑不起来" tabindex="-1">模式三：代码跑不起来 <a class="header-anchor" href="#模式三-代码跑不起来" aria-label="Permalink to &quot;模式三：代码跑不起来&quot;">​</a></h3><p><strong>引述</strong>：Pocock 再次引用《程序员修炼之道》——&quot;始终采取小而谨慎的步骤。反馈的频率就是你的速度上限。永远不要承担过大的任务。&quot;</p><p><strong>本质</strong>：反馈回路断了。人类程序员有持续的多层反馈：IDE 的静态检查、浏览器 DevTools、单元测试、甚至&quot;这行写完感觉不对劲&quot;的直觉。Agent 没有这些——它看到的只有 prompt 和自己生成的文本。</p><p><strong>解决方案</strong>：显式重建多层反馈回路——静态类型 + 浏览器访问 + 自动化测试。在测试层面，红-绿-重构循环是关键纪律：Agent 必须先写一个会失败的测试，然后写最小的实现让它通过，再在有测试保护的前提下重构。</p><p><strong>对应技能</strong>：</p><table tabindex="0"><thead><tr><th>技能</th><th>核心功能</th></tr></thead><tbody><tr><td><code>/tdd</code></td><td>红-绿-重构循环，按垂直切片推进，附 6 个参考文档</td></tr><tr><td><code>/diagnose</code></td><td>结构化调试循环：复现 → 最小化 → 假设 → 插桩 → 修复 → 回归测试</td></tr></tbody></table><p><strong>工程判断内建</strong>：<code>/tdd</code> 不是简单地说&quot;请用 TDD&quot;，而是内建了具体的工程判断——测试应该验证公共接口而非实现细节；禁止水平切片（一次性写完所有测试再写实现），必须垂直切片（一个测试 → 一个最小实现 → 循环）。</p><h3 id="模式四-我们造了一团泥球" tabindex="-1">模式四：我们造了一团泥球 <a class="header-anchor" href="#模式四-我们造了一团泥球" aria-label="Permalink to &quot;模式四：我们造了一团泥球&quot;">​</a></h3><p><strong>引述</strong>：Pocock 引用 Kent Beck（&quot;每天都要投资于系统的设计&quot;）和 John Ousterhout（&quot;最好的模块是深的——它们允许通过简单的接口访问大量功能&quot;）。</p><p><strong>本质</strong>：这是前三个模式的总和与终局。Agent 没理解需求 → 反复修补 → 代码冗余堆积。Agent 没有共享语言 → 命名混乱 → 模块边界模糊。Agent 没有反馈回路 → bug 被埋在深处 → 越改越乱。</p><p><strong>AI 时代的独特加速</strong>：Agent 加速编码的同时也在加速软件熵增——代码库以史无前例的速度变得复杂。</p><p><strong>解决方案</strong>：三层防御机制——</p><table tabindex="0"><thead><tr><th>时机</th><th>技能</th><th>作用</th></tr></thead><tbody><tr><td>进入时</td><td><code>/to-prd</code></td><td>质询你将要触及哪些模块</td></tr><tr><td>过程中</td><td><code>/zoom-out</code></td><td>强制 Agent 在理解某段代码时将其放在整个系统的上下文中</td></tr><tr><td>恶化后</td><td><code>/improve-codebase-architecture</code></td><td>利用 CONTEXT.md 和 ADR，从泥球中发现&quot;深模块&quot;机会并逐步重建架构边界</td></tr></tbody></table><p><strong>Pocock 建议每隔几天就运行一次</strong> <code>/improve-codebase-architecture</code>——这不是随意的经验之谈，背后是对&quot;AI 让代码腐化不可逆&quot;这一事实的诚实面对。</p><hr><h2 id="三、技能体系全景" tabindex="-1">三、技能体系全景 <a class="header-anchor" href="#三、技能体系全景" aria-label="Permalink to &quot;三、技能体系全景&quot;">​</a></h2><h3 id="技能分类-user-invoked-vs-model-invoked" tabindex="-1">技能分类：User-invoked vs Model-invoked <a class="header-anchor" href="#技能分类-user-invoked-vs-model-invoked" aria-label="Permalink to &quot;技能分类：User-invoked vs Model-invoked&quot;">​</a></h3><p>这是 Pocock 技能体系中最精妙的设计之一：</p><ul><li><strong>User-invoked（用户调用）</strong>：你主动调用（如 <code>/grill-me</code>），其工作是&quot;编排&quot;——协调多个 Agent 行为</li><li><strong>Model-invoked（模型调用）</strong>：你可以调用，Agent 也可以自动判断后调用；其工作是&quot;可复用的纪律&quot;</li></ul><p><strong>一个用户调用技能可以调用多个模型调用技能，但用户调用技能之间互不调用。</strong> 这保证了用户始终是决策者——Agent 不会在用户不知情的情况下&quot;启动一个技能链&quot;。</p><h3 id="完整技能清单" tabindex="-1">完整技能清单 <a class="header-anchor" href="#完整技能清单" aria-label="Permalink to &quot;完整技能清单&quot;">​</a></h3><p><strong>Engineering（工程类——日常编码）</strong></p><table tabindex="0"><thead><tr><th>技能</th><th>类型</th><th>核心功能</th></tr></thead><tbody><tr><td><code>/setup-matt-pocock-skills</code></td><td>User</td><td>项目一次性配置：issue tracker + triage labels + domain docs</td></tr><tr><td><code>/grill-with-docs</code></td><td>User</td><td>需求深访 + 建立 CONTEXT.md + 生成 ADR</td></tr><tr><td><code>/tdd</code></td><td>Model</td><td>红-绿-重构循环，垂直切片推进</td></tr><tr><td><code>/diagnose</code></td><td>Model</td><td>复现→最小化→假设→插桩→修复→回归测试</td></tr><tr><td><code>/triage</code></td><td>User</td><td>按状态机处理 issue 流转</td></tr><tr><td><code>/to-prd</code></td><td>User</td><td>将当前对话合成为 PRD 并发布到 issue tracker</td></tr><tr><td><code>/to-issues</code></td><td>User</td><td>将 PRD 拆分为可独立抓取的垂直切片 issue</td></tr><tr><td><code>/improve-codebase-architecture</code></td><td>User</td><td>扫描代码库，发现深模块机会，生成 HTML 可视化报告</td></tr><tr><td><code>/zoom-out</code></td><td>Model</td><td>将代码段放在整个系统上下文中阐释</td></tr><tr><td><code>/prototype</code></td><td>Model</td><td>构建可丢弃的原型（终端应用/多 UI 方案）</td></tr></tbody></table><p><strong>Productivity（生产力类——非代码场景）</strong></p><table tabindex="0"><thead><tr><th>技能</th><th>类型</th><th>核心功能</th></tr></thead><tbody><tr><td><code>/grill-me</code></td><td>User</td><td>通用需求深访，直到决策树的每个分支都解决</td></tr><tr><td><code>/caveman</code></td><td>Model</td><td>~75% token 缩减，去掉填充词，保留技术准确性</td></tr><tr><td><code>/write-a-skill</code></td><td>User</td><td>脚手架生成新的 SKILL.md</td></tr></tbody></table><p><strong>Misc（工具类）</strong></p><table tabindex="0"><thead><tr><th>技能</th><th>核心功能</th></tr></thead><tbody><tr><td><code>/git-guardrails-claude-code</code></td><td>安装钩子，阻止危险 git 命令</td></tr><tr><td><code>/setup-pre-commit</code></td><td>Husky + lint-staged + Prettier + type-check + tests</td></tr><tr><td><code>/scaffold-exercises</code></td><td>课程练习目录生成</td></tr><tr><td><code>/migrate-to-shoehorn</code></td><td>替换 <code>as</code> 类型断言</td></tr></tbody></table><hr><h2 id="四、实战流程-从零构建秒杀系统" tabindex="-1">四、实战流程：从零构建秒杀系统 <a class="header-anchor" href="#四、实战流程-从零构建秒杀系统" aria-label="Permalink to &quot;四、实战流程：从零构建秒杀系统&quot;">​</a></h2><p>视频演示的完整流程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Idea → Research → Prototype → PRD → Kanban → Implementation → QA/Code Review</span></span></code></pre></div><h3 id="_1-项目初始化-setup-matt-pocock-skills" tabindex="-1">1. 项目初始化：<code>/setup-matt-pocock-skills</code> <a class="header-anchor" href="#_1-项目初始化-setup-matt-pocock-skills" aria-label="Permalink to &quot;1. 项目初始化：`/setup-matt-pocock-skills`&quot;">​</a></h3><p>一次性配置三个决策：</p><table tabindex="0"><thead><tr><th>配置项</th><th>选项</th><th>默认</th></tr></thead><tbody><tr><td>Issue Tracker</td><td>GitHub Issues / GitLab Issues / 本地 Markdown</td><td>GitHub</td></tr><tr><td>Triage Labels</td><td>5 个状态标签的自定义映射</td><td>默认名称</td></tr><tr><td>Domain Docs</td><td>单一上下文（单体项目）/ 多上下文（多模块）</td><td>单一上下文</td></tr></tbody></table><h3 id="_2-需求访谈-grill-with-docs" tabindex="-1">2. 需求访谈：<code>/grill-with-docs</code> <a class="header-anchor" href="#_2-需求访谈-grill-with-docs" aria-label="Permalink to &quot;2. 需求访谈：`/grill-with-docs`&quot;">​</a></h3><p>不是简单的&quot;头脑风暴&quot;——是结构化的深度访谈。Agent 从 6 个维度连续追问：</p><ul><li>功能范围（&quot;这个功能包含什么？不包含什么？&quot;）</li><li>边界条件（&quot;空输入怎么办？并发怎么办？&quot;）</li><li>错误处理（&quot;失败了怎么恢复？&quot;）</li><li>性能要求（&quot;期望的 QPS？P99 延迟？&quot;）</li><li>技术栈约束（&quot;必须用 Redis 吗？&quot;）</li><li>测试策略（&quot;哪些路径必须测试？&quot;）</li></ul><p><strong>产出</strong>：CONTEXT.md（领域术语表）+ ADR（架构决策记录）</p><h3 id="_3-生成-prd-to-prd" tabindex="-1">3. 生成 PRD：<code>/to-prd</code> <a class="header-anchor" href="#_3-生成-prd-to-prd" aria-label="Permalink to &quot;3. 生成 PRD：`/to-prd`&quot;">​</a></h3><p>将访谈对话合成为结构化 PRD，包含：用户故事、实现决策、技术栈、数据库设计、API 路由。</p><h3 id="_4-开发阶段-三种路径" tabindex="-1">4. 开发阶段：三种路径 <a class="header-anchor" href="#_4-开发阶段-三种路径" aria-label="Permalink to &quot;4. 开发阶段：三种路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>路径</th><th>使用场景</th><th>技能</th></tr></thead><tbody><tr><td>直接开发</td><td>需求清晰、改动小</td><td>AI 读 PRD 后直接编码</td></tr><tr><td>计划驱动</td><td>复杂改动、需要多步协调</td><td>Claude Code Prime 模式</td></tr><tr><td>测试驱动</td><td>核心逻辑、需要高可靠性</td><td><code>/tdd</code></td></tr></tbody></table><h3 id="_5-原型设计-可选-prototype" tabindex="-1">5. 原型设计（可选）：<code>/prototype</code> <a class="header-anchor" href="#_5-原型设计-可选-prototype" aria-label="Permalink to &quot;5. 原型设计（可选）：`/prototype`&quot;">​</a></h3><ul><li>逻辑原型：可运行的终端应用</li><li>设计原型：1-3 个 UI 方案，可切换预览</li></ul><hr><h2 id="五、与-gsd-的对比-为什么-简单-赢了" tabindex="-1">五、与 GSD 的对比：为什么&quot;简单&quot;赢了 <a class="header-anchor" href="#五、与-gsd-的对比-为什么-简单-赢了" aria-label="Permalink to &quot;五、与 GSD 的对比：为什么&quot;简单&quot;赢了&quot;">​</a></h2><h3 id="gsd-的失败模式" tabindex="-1">GSD 的失败模式 <a class="header-anchor" href="#gsd-的失败模式" aria-label="Permalink to &quot;GSD 的失败模式&quot;">​</a></h3><p>GSD（Generate-Specify-Develop）试图通过规定流程来保证质量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GSD: 需求 → 规格（必须）→ 开发（必须按规格）→ 测试（必须通过）</span></span></code></pre></div><p>问题：<strong>流程越刚性，开发者越被动。</strong> 当需求变了（它一定会变），整个流程需要重新走一遍。当 Agent 在某个步骤卡住了，开发者没有工具来&quot;跳过&quot;或&quot;调整&quot;——只能等流程走完。</p><h3 id="pocock-的替代方案" tabindex="-1">Pocock 的替代方案 <a class="header-anchor" href="#pocock-的替代方案" aria-label="Permalink to &quot;Pocock 的替代方案&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pocock: 工具箱（grill / tdd / diagnose / prototype / to-prd / to-issues）</span></span></code></pre></div><p><strong>不是&quot;少了流程&quot;，而是&quot;把流程的控制权还给开发者&quot;。</strong> 你知道什么时候需要需求访谈，什么时候需要 TDD，什么时候需要原型——不需要一个框架来告诉你。</p><h3 id="对齐我们的-soul-自进化原则" tabindex="-1">对齐我们的 SOUL 自进化原则 <a class="header-anchor" href="#对齐我们的-soul-自进化原则" aria-label="Permalink to &quot;对齐我们的 SOUL 自进化原则&quot;">​</a></h3><p>Pocock 的&quot;模型越强，技能越简单&quot;与我们的自进化原则完全同构：</p><ul><li><strong>我们的原则</strong>：&quot;能力要复用——重复出现的问题 → 沉淀为 skill，不要每次重做&quot;</li><li><strong>Pocock 的原则</strong>：每个 skill 是独立的、可修改的、可组合的——不是&quot;流程&quot;，是&quot;模式&quot;</li></ul><p><strong>技能的&quot;简单&quot;不是&quot;简陋&quot;——是&quot;把复杂留给 Agent 的判断力，把控制留给开发者的判断力&quot;。</strong></p><hr><h2 id="六、与现有知识库的深度连接" tabindex="-1">六、与现有知识库的深度连接 <a class="header-anchor" href="#六、与现有知识库的深度连接" aria-label="Permalink to &quot;六、与现有知识库的深度连接&quot;">​</a></h2><h3 id="_6-1-llm-wiki-gbrain-context-md-是-agent-的知识库" tabindex="-1">6.1 LLM Wiki / GBrain：CONTEXT.md 是 Agent 的知识库 <a class="header-anchor" href="#_6-1-llm-wiki-gbrain-context-md-是-agent-的知识库" aria-label="Permalink to &quot;6.1 LLM Wiki / GBrain：CONTEXT.md 是 Agent 的知识库&quot;">​</a></h3><p>CONTEXT.md 是 LLM Wiki 的&quot;微缩版&quot;——它实现了&quot;写入时编译&quot;的核心思想：</p><table tabindex="0"><thead><tr><th>维度</th><th>GBrain</th><th>CONTEXT.md</th></tr></thead><tbody><tr><td>编译者</td><td>LLM（Dream Cycle）</td><td>LLM（grill-with-docs）</td></tr><tr><td>结构</td><td>Compiled Truth + Timeline</td><td>领域术语 + 架构约束</td></tr><tr><td>更新</td><td>夜间自动</td><td>每次需求访谈增量更新</td></tr><tr><td>使用</td><td>检索时读取</td><td>Agent 每次交互前读取</td></tr></tbody></table><p><strong>Pocock 的共享语言本质上就是 GBrain 的 Compiled Truth——&quot;你相信什么&quot;和&quot;你为什么相信&quot;被清晰分开。</strong></p><h3 id="_6-2-认知萎缩-共享语言是对抗认知负债的疫苗" tabindex="-1">6.2 认知萎缩：共享语言是对抗认知负债的疫苗 <a class="header-anchor" href="#_6-2-认知萎缩-共享语言是对抗认知负债的疫苗" aria-label="Permalink to &quot;6.2 认知萎缩：共享语言是对抗认知负债的疫苗&quot;">​</a></h3><p><strong>核心连接</strong>：Pocock 的&quot;模式二&quot;（Agent 表达啰嗦）直接对应认知萎缩假说中的&quot;系统熵增&quot;——当 Agent 没有共享语言，每次交互都是从零建模，认知负载指数增长。</p><p><strong>CONTEXT.md 是认知假体（cognitive prosthesis）</strong>——不是替代你的思考，而是让你和 Agent 共享同一个概念空间，避免&quot;每次都要重新解释什么是物化级联&quot;。</p><h3 id="_6-3-代码-状态分离-跨领域合成模式-1" tabindex="-1">6.3 代码-状态分离（跨领域合成模式 #1） <a class="header-anchor" href="#_6-3-代码-状态分离-跨领域合成模式-1" aria-label="Permalink to &quot;6.3 代码-状态分离（跨领域合成模式 #1）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>技能体系：</span></span>\n<span class="line"><span>  代码层 = SKILL.md（技能定义，不变）</span></span>\n<span class="line"><span>  状态层 = CONTEXT.md + ADR（共享知识，持续演化）</span></span>\n<span class="line"><span>  执行层 = Agent 的每次运行（实例化，临时）</span></span></code></pre></div><p><strong>与 LLM Wiki 的编译过程同构</strong>：原始文档（代码）→ 编译页面（状态）→ 查询时读取（执行）。</p><h3 id="_6-4-摩擦假说-pocock-的技能是-战略性摩擦" tabindex="-1">6.4 摩擦假说：Pocock 的技能是&quot;战略性摩擦&quot; <a class="header-anchor" href="#_6-4-摩擦假说-pocock-的技能是-战略性摩擦" aria-label="Permalink to &quot;6.4 摩擦假说：Pocock 的技能是&quot;战略性摩擦&quot;&quot;">​</a></h3><p><strong>这是最深刻的连接。</strong> Pocock 技能体系的每一个环节都在<strong>刻意增加摩擦</strong>：</p><table tabindex="0"><thead><tr><th>技能</th><th>增加的摩擦</th><th>消除的摩擦</th></tr></thead><tbody><tr><td><code>/grill-with-docs</code></td><td>需求访谈（10-30 分钟）</td><td>方向错误（数小时返工）</td></tr><tr><td><code>/tdd</code></td><td>先写测试（5-15 分钟）</td><td>回归 bug（数小时排查）</td></tr><tr><td><code>/diagnose</code></td><td>结构化调试（15-60 分钟）</td><td>随机修补（数天累积）</td></tr><tr><td><code>/improve-codebase-architecture</code></td><td>定期扫描（30-60 分钟/周）</td><td>架构腐化（数月重构）</td></tr></tbody></table><p><strong>Pocock 不是&quot;增加摩擦&quot;——他是&quot;把摩擦放在正确的位置&quot;。</strong> 在需求阶段投入 30 分钟摩擦，省去开发阶段 3 小时的方向错误。这完全符合我们的 Friction Hypothesis 核心论点：<strong>不是所有摩擦都是坏的——关键摩擦是&quot;认知免疫系统&quot;，消除它会导致系统性脆弱。</strong></p><h3 id="_6-5-激活函数进化-从-开关-到-旋钮" tabindex="-1">6.5 激活函数进化：从&quot;开关&quot;到&quot;旋钮&quot; <a class="header-anchor" href="#_6-5-激活函数进化-从-开关-到-旋钮" aria-label="Permalink to &quot;6.5 激活函数进化：从&quot;开关&quot;到&quot;旋钮&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时代</th><th>开发流程</th><th>激活函数</th></tr></thead><tbody><tr><td>传统</td><td>瀑布模型（线性、不可逆）</td><td>Sigmoid（二值开关）</td></tr><tr><td>敏捷</td><td>Scrum（迭代、可调整）</td><td>ReLU（半开关）</td></tr><tr><td>GSD</td><td>流程控制（强制步骤）</td><td>硬截断</td></tr><tr><td>mattpocock-skills</td><td>可组合工具箱（按需取用）</td><td>SwiGLU（连续旋钮）</td></tr></tbody></table><p><strong>mattpocock-skills 是 AI 开发流程的 SwiGLU 化——从&quot;你必须走这几步&quot;到&quot;你可以按需组合这些技能&quot;。</strong></p><h3 id="_6-6-pentagi-的知识图谱-技能体系的-经验积累" tabindex="-1">6.6 PentAGI 的知识图谱：技能体系的&quot;经验积累&quot; <a class="header-anchor" href="#_6-6-pentagi-的知识图谱-技能体系的-经验积累" aria-label="Permalink to &quot;6.6 PentAGI 的知识图谱：技能体系的&quot;经验积累&quot;&quot;">​</a></h3><p>PentAGI 用 Graphiti + Neo4j 跨任务积累攻击经验。mattpocock-skills 用 CONTEXT.md + ADR 跨会话积累领域知识。<strong>两者都是&quot;持久化记忆&quot;——Agent 不会在每次对话后重置。</strong></p><table tabindex="0"><thead><tr><th>系统</th><th>记忆载体</th><th>更新方式</th><th>检索方式</th></tr></thead><tbody><tr><td>PentAGI</td><td>Neo4j 知识图谱</td><td>每次攻击后自动</td><td>图遍历</td></tr><tr><td>GBrain</td><td>Markdown（Git）</td><td>Dream Cycle 夜间</td><td>混合搜索（RRF）</td></tr><tr><td>mattpocock-skills</td><td>CONTEXT.md + ADR</td><td>每次需求访谈</td><td>Agent 每次交互前读取</td></tr><tr><td>我们的系统</td><td>topics/ + memory/</td><td>手动整理</td><td>memory_search + grep</td></tr></tbody></table><h3 id="_6-7-与我们的技能体系对比" tabindex="-1">6.7 与我们的技能体系对比 <a class="header-anchor" href="#_6-7-与我们的技能体系对比" aria-label="Permalink to &quot;6.7 与我们的技能体系对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>我们的系统</th><th>mattpocock-skills</th></tr></thead><tbody><tr><td>技能粒度</td><td>中（知识分析、同步、维护）</td><td>小（单个工程活动）</td></tr><tr><td>可组合性</td><td>中（按主题组织）</td><td>高（独立可组合）</td></tr><tr><td>共享知识</td><td>MEMORY.md + topics/</td><td>CONTEXT.md + ADR</td></tr><tr><td>自动积累</td><td>部分（维护脚本）</td><td>高（grill-with-docs）</td></tr><tr><td>适用域</td><td>知识管理 + 分析</td><td>软件工程</td></tr></tbody></table><p><strong>可借鉴的方向</strong>：</p><ol><li>引入&quot;共享语言&quot;概念——为每个 topic 创建类似 CONTEXT.md 的术语表</li><li>引入&quot;用户调用 vs 模型调用&quot;分类——让技能体系更清晰</li><li>引入&quot;垂直切片&quot;思想——知识整理按&quot;一个主题一个文件&quot;推进，而非&quot;一次整理所有主题&quot;</li></ol><hr><h2 id="七、历史平行" tabindex="-1">七、历史平行 <a class="header-anchor" href="#七、历史平行" aria-label="Permalink to &quot;七、历史平行&quot;">​</a></h2><h3 id="工匠的工具箱-→-宜家的说明书-→-ai-的-技能工具箱" tabindex="-1">工匠的工具箱 → 宜家的说明书 → AI 的&quot;技能工具箱&quot; <a class="header-anchor" href="#工匠的工具箱-→-宜家的说明书-→-ai-的-技能工具箱" aria-label="Permalink to &quot;工匠的工具箱 → 宜家的说明书 → AI 的&quot;技能工具箱&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时代</th><th>范式</th><th>代表</th></tr></thead><tbody><tr><td>前工业</td><td>工匠的工具箱（每个工匠有自己的工具，按需取用）</td><td>学徒制</td></tr><tr><td>工业</td><td>流水线说明书（标准化流程，工人不可偏离）</td><td>福特制</td></tr><tr><td>敏捷</td><td>Scrum 框架（流程 + 灵活性的折中）</td><td>Jira</td></tr><tr><td>AI 时代（GSD）</td><td>机器人流程（Agent 严格执行步骤）</td><td>GSD/BMAD</td></tr><tr><td>AI 时代（Pocock）</td><td>工匠的工具箱回归（Agent 按需调用技能）</td><td>mattpocock-skills</td></tr></tbody></table><p><strong>Pocock 的&quot;技能工具箱&quot;是前工业时代工匠精神的数字回归——不是&quot;流程自动化&quot;，而是&quot;判断力增强&quot;。</strong></p><h3 id="类型系统-→-技能系统" tabindex="-1">类型系统 → 技能系统 <a class="header-anchor" href="#类型系统-→-技能系统" aria-label="Permalink to &quot;类型系统 → 技能系统&quot;">​</a></h3><p>Pocock 是 TypeScript 布道者——这并非偶然。TypeScript 的核心思想是&quot;在编译时捕获错误，而不是运行时&quot;。mattpocock-skills 的核心思想是&quot;在需求访谈时捕获错误，而不是在编码时&quot;。</p><p><strong>技能之于 AI 交互，如同类型系统之于代码——在错误的代价还很小的时候，把它找出来。</strong></p><hr><h2 id="八、核心判断" tabindex="-1">八、核心判断 <a class="header-anchor" href="#八、核心判断" aria-label="Permalink to &quot;八、核心判断&quot;">​</a></h2><ol><li><p><strong>&quot;模型越强，技能越简单&quot;不是口号，是工程洞察。</strong> 当模型足够强，它不需要被&quot;管&quot;——它需要被&quot;引导&quot;。技能不是&quot;替代判断&quot;，是&quot;增强判断&quot;。</p></li><li><p><strong>四个失败模式构成了一条因果链</strong>：需求错位 → 沟通冗余 → 质量缺失 → 架构腐化。每一个模式的解决方案对应一类技能，技能之间又通过共享数据（CONTEXT.md、ADR）相互关联。这不是巧合——这是工程学。</p></li><li><p><strong>Pocock 的技能是&quot;战略性摩擦&quot;。</strong> 在需求阶段投入 30 分钟，省去开发阶段 3 小时的方向错误。这与我们的 Friction Hypothesis 完全同构——不是所有摩擦都是坏的，关键摩擦是免疫系统。</p></li><li><p><strong>CONTEXT.md 是 LLM Wiki 的微缩版。</strong> 共享语言 = 编译后的知识。每次交互前读取，每次需求访谈后更新——&quot;写入时编译，查询时读取&quot;。</p></li><li><p><strong>&quot;技能&quot;不是&quot;剧本&quot;——它是&quot;语法&quot;。</strong> GSD 是剧本（固定步骤），Pocock 是语法（可组合模式）。这决定了 AI 开发工具的最终形态——不是&quot;管住 AI&quot;，是&quot;让 AI 和开发者说同一种语言&quot;。</p></li><li><p><strong>与我们的系统高度互补。</strong> 我们的系统有深度分析（跨领域连接、历史平行、反事实推演），Pocock 有工程纪律（grill、TDD、diagnose、architecture）。两者结合 = 理想的知识工作技能体系。</p></li></ol><hr><h2 id="九、关联阅读" tabindex="-1">九、关联阅读 <a class="header-anchor" href="#九、关联阅读" aria-label="Permalink to &quot;九、关联阅读&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/ai-system-architecture/llm-wiki-gbrain-knowledge-paradigm.html">LLM Wiki &amp; GBrain 知识库新范式</a> — CONTEXT.md 是微缩版 LLM Wiki</li><li><a href="/zhishiku-reading/topics/ai-system-architecture/cognitive-atrophy-knowledge.html">认知萎缩与摩擦假说</a> — 共享语言对抗认知负债</li><li><a href="/zhishiku-reading/topics/cybersecurity/pentagi-autonomous-pentest.html">PentAGI 自主渗透测试</a> — Agent 持久化记忆</li><li><a href="/zhishiku-reading/topics/ai-system-architecture/activation-function-evolution.html">激活函数进化史</a> — 从 GSD（开关）到技能工具箱（旋钮）</li><li><a href="/zhishiku-reading/topics/cross-domain-synthesis-2026-q3.html">跨领域合成 2026 Q3</a> — 代码-状态分离模式</li><li><a href="/zhishiku-reading/topics/ai-system-architecture/ai-industry-2026-q3-knowledge.html">AI 产业趋势 2026 Q3</a> — Agent 记忆基础设施</li></ul><hr><p><em>整理：2026-07-09</em></p>',127)])])}const q=o(r,[["render",i]]);export{p as __pageData,q as default};
